    function clean(s) {
        return String(s || "").replace(/\s+/g, " ").replace(/\s*[?:]\s*$/, "").trim();
    }

    function normHelp(s) {
        return String(s || "").replace(/[\u2066-\u2069]/g, "").replace(/\s+/g, " ").trim().toLowerCase();
    }

